for q in "anchor numeric estimates" "reanalysis open data multi-lab" "cognitive model decision heuristics" "judgment decision making bias replication"; do echo "## $q"; curl -s -A "mailto:[email redacted]" "https://api.crossref.org/works?query.bibliographic=$(python3 -c "import urllib.parse,sys;print(urllib.parse.quote(sys.argv[1]))" "$q")&filter=issn:2474-7394,from-pub-date:2021&rows=8&select=DOI,title,published" > /tmp/scratch_collabra_cr.json; python3 -c "
import json
try:
  for it in json.load(open('/tmp/scratch_collabra_cr.json'))['message']['items']:
    print(it['DOI'], '|', it.get('title',[''])[0][:130], '|', it.get('published',{}).get('date-parts'))
except Exception as e: print('ERR', open('/tmp/scratch_collabra_cr.json').read()[:200])
"; sleep 2; done

